result = await mcp.call_tool("tools", "ox-bridge-write", {"path": "/workspace/test_synthgen.py", "content": "import hashlib
import json
import subprocess
import sys

import pytest

from synthgen import generate_patients


def rows_of(seed, count):
    return generate_patients(seed, count)


def write_jsonl(path, patients):
    with open(path, "w", encoding="utf-8") as f:
        for p in patients:
            f.write(json.dumps(p) + "\n")
    with open(path, "rb") as f:
        return hashlib.sha256(f.read()).hexdigest()


def run_cli(tmp_path, seed, count):
    out = tmp_path / f"p_{seed}_{count}.jsonl"
    subprocess.run(
        [sys.executable, "synthgen.py", "--seed", str(seed), "--count", str(count), "--out", str(out)],
        check=True,
    )
    return out


# ---------- determinism tests ----------

def test_same_seed_identical_bytes(tmp_path):
    h1 = write_jsonl(tmp_path / "a.jsonl", rows_of(42, 200))
    h2 = write_jsonl(tmp_path / "b.jsonl", rows_of(42, 200))
    assert h1 == h2


def test_cli_same_seed_identical_bytes(tmp_path):
    o1 = run_cli(tmp_path, 42, 200)
    o2 = run_cli(tmp_path, 42, 200)
    assert hashlib.sha256(o1.read_bytes()).hexdigest() == hashlib.sha256(o2.read_bytes()).hexdigest()


def test_different_seeds_differ(tmp_path):
    h1 = write_jsonl(tmp_path / "a.jsonl", rows_of(42, 500))
    h2 = write_jsonl(tmp_path / "b.jsonl", rows_of(43, 500))
    assert h1 != h2


def test_cli_matches_library(tmp_path):
    """CLI output must equal in-process generation (same serialization path)."""
    out = run_cli(tmp_path, 42, 200)
    lib = "".join(json.dumps(p) + "\n" for p in rows_of(42, 200))
    assert out.read_text(encoding="utf-8") == lib


# ---------- schema / integrity tests ----------

@pytest.fixture(scope="module")
def big_rows():
    return rows_of(1234, 5000)


def test_ids_unique_and_wellformed(big_rows):
    ids = [r["id"] for r in big_rows]
    assert len(ids) == len(set(ids)) == 5000
    for pid in ids:
        assert pid.startswith("SP") and len(pid) == 8 and pid[2:].isdigit()


def test_row_count(big_rows):
    assert len(big_rows) == 5000


def test_sex_roughly_balanced(big_rows):
    sexes = [r["sex"] for r in big_rows]
    assert set(sexes) <= {"F", "M"}
    frac_f = sexes.count("F") / len(sexes)
    assert abs(frac_f - 0.5) < 0.05


# ---------- statistical checks (seed fixed at 1234, 5000 rows) ----------

def test_mean_sbp(big_rows):
    mean = sum(r["sbp"] for r in big_rows) / len(big_rows)
    assert abs(mean - 118.0) < 1.5, f"mean sbp {mean:.3f} outside 118 +/- 1.5"


def test_missing_hr_fraction(big_rows):
    missing = sum(1 for r in big_rows if "heart_rate" not in r) / len(big_rows)
    assert abs(missing - 0.08) < 0.02, f"missing fraction {missing:.4f} outside 0.08 +/- 0.02"


def test_clamps_respected(big_rows):
    for r in big_rows:
        assert 0 <= r["age"] <= 100 and isinstance(r["age"], int)
        assert isinstance(r["age"], int)
        assert 70 <= r["sbp"] <= 220 and isinstance(r["sbp"], int)
        if "heart_rate" in r:
            assert 30 <= r["heart_rate"] <= 190 and isinstance(r["heart_rate"], int)


def test_age_distribution_shape(big_rows):
    """Triangular(0, 40, 100): mode near 40; mean ~46.7."""
    ages = [r["age"] for r in big_rows]
    mean = sum(ages) / len(ages)
    assert abs(mean - 100.0 / 3.0 * 1.4) < 3.0  # theoretical mean = 140/3 ≈ 46.67
    below_mode = sum(1 for a in ages if a < 40)
    above_mode = sum(1 for a in ages if a > 40)
    # For triangular, mass below mode = mode/(hi-lo) = 0.4
    assert abs(below_mode / len(ages) - 0.4) < 0.05
